            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Como em jogo de cabra-cega, em que há seres à nossa volta, a pergunta orienta-se entre os que lhe não pertencem até achar o que procura.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "O grande sonho de todo o escritor - se o tiver - será o de nunca encontrar o leitor «ideal». Porque se o encontrasse, a sua obra morreria aí. Cada leitor, com efeito, recria a obra que lê; e a perpetuidade de uma obra significará a sua perpétua recriação.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Quanto maior se é, mais repetido se é. Platão, Aristóteles, Kant, quantos outros. Ainda se não calaram nos que deles falaram. E é possível que só se calem quando a espécie humana se calar.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Há os livros que antes de lidos já estão lidos. Há os que se lêem todos e ficam logo lidos todos. E há os que nos regateiam a leitura e que pedimos humildemente que se deixem ler todos e não deixam e vão largando uma parte de si pelas gerações e jamais se deixam ler de uma vez para sempre.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Quando se apanha um mentiroso, ele pode perguntar-nos: \"e o que é verdade?\" E o mais provável é termos de o deixar seguir.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "De vez em quando a eternidade sai do teu interior e a contingência substitui-a com o seu pânico. São os amigos e conhecidos que vão desaparecendo e deixam um vazio irrespirável. Não é a sua 'falta' que falta, é o desmentido de que tu não morres.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Para que percorres inutilmente o céu inteiro à procura da tua estrela? Põe-na lá.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Por detrás de um triunfo há sempre uma vingança. E é numa razão directa que varia a sua grandeza.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Não se pode verdadeiramente admirar senão quem está longe. Porque só a distância nos garante que não cheire mal da boca.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Há monumentos ao soldado desconhecido. Mas não há um só aos heróis a que não calhou poderem sê-lo.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "O comunismo distingue-se fundamentalmente do fascismo porque foi o primeiro.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Somos um povo de analfabetos. Destes há alguns que não sabem ler.", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "Há muitos monumentos ao «soldado desconhecido». Houve mesmo a invocação de um «Deus Desconhecido\". Mas não há nenhum altar ao \"santo desconhecido\" ou uma referência ao \"artista desconhecido\".", Author = "Vergílio Ferreira" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Vergílio_Ferreira", Text = "O amor [...] é uma longa paciência.", Author = "Vergílio Ferreira" },
